package org.sleepwell.app;
import android.content.Context;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;
/** Retained review/confirmation. Replacement cannot be cancelled once its transaction preparation begins. */
final class LibraryAudioImportJob {
 enum Phase{IDLE,CHOOSING,READING,REVIEW,RESTORING,DONE,ERROR}
 static final class State {final Phase phase;final LibraryAudioImport.Review review;final String message;State(Phase phase,LibraryAudioImport.Review review,String message){this.phase=phase;this.review=review;this.message=message;}}
 interface Observer {void changed(State state);}
 private static final Executor CANCEL=new ThreadPoolExecutor(0,1,10,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"audio-import-cancel");t.setDaemon(true);return t;},new ThreadPoolExecutor.DiscardPolicy());
 final Context app;final Records.Factory records;final Handler main=new Handler(Looper.getMainLooper());final ExecutorService worker=Executors.newSingleThreadExecutor();final AtomicReference<CancellationSignal> signal=new AtomicReference<>();final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private WeakReference<Observer> observer=new WeakReference<>(null);private volatile boolean closed;private volatile State state;private LibraryAudioImport.Review owned;
 LibraryAudioImportJob(Context context,Records.Factory factory,boolean restarted){app=context.getApplicationContext();records=factory;state=new State(Phase.IDLE,null,restarted?"The app restarted. Review current records before retrying, and choose the ZIP again. No automatic import resumes.":"");}
 State state(){return state;}void observe(Observer value){observer=new WeakReference<>(value);value.changed(state);}void detach(Observer value){if(observer.get()==value)observer.clear();}private void publish(State value){if(closed)return;state=value;Observer target=observer.get();if(target!=null)target.changed(value);}
 boolean choose(){if(closed||state.phase==Phase.READING||state.phase==Phase.RESTORING||state.phase==Phase.REVIEW||state.phase==Phase.CHOOSING)return false;publish(new State(Phase.CHOOSING,null,"Choose a restorable SleepWell audio ZIP."));return true;}
 void choiceCancelled(){if(state.phase==Phase.CHOOSING)publish(new State(Phase.IDLE,null,"No ZIP selected. Local data is unchanged."));}
 private static String notice(Exception error){String value=error.getMessage();if(value==null||value.isBlank()||value.length()>320||error instanceof FileNotFoundException)return "The audio ZIP or document provider is unavailable.";return value;}
 void read(Uri source){if(closed||state.phase!=Phase.CHOOSING)return;if(source==null||!"content".equals(source.getScheme())){publish(new State(Phase.ERROR,null,"Choose a ZIP through Android Files."));return;}publish(new State(Phase.READING,null,"Reading and validating every recording…"));long admission=BackupRuntime.generation();worker.execute(()->{try{BackupRuntime.requireIdle(app,admission);CancellationSignal cancellation=new CancellationSignal();signal.set(cancellation);try{NightAudioArchive.active(()->!closed);ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(source,"r",cancellation);if(file==null)throw new IOException("The audio ZIP is unavailable.");descriptor.set(file);try(InputStream input=new ParcelFileDescriptor.AutoCloseInputStream(file)){owned=LibraryAudioImport.read(app,records,input,()->!closed,admission);}finally{descriptor.compareAndSet(file,null);}}finally{signal.compareAndSet(cancellation,null);}LibraryAudioImport.Review review=owned;main.post(()->publish(new State(Phase.REVIEW,review,"Review before replacing local data. Nothing has been replaced yet.")));}catch(Exception error){String failure=notice(error);main.post(()->publish(new State(Phase.ERROR,null,"ZIP could not be read: "+failure+" Local records and audio were not replaced.")));}});}
 void confirm(){if(closed||state.phase!=Phase.REVIEW||state.review==null)return;LibraryAudioImport.Review review=state.review;publish(new State(Phase.RESTORING,review,"Copying validated audio and replacing metadata…"));worker.execute(()->{String result="",failure="";try{result=LibraryAudioImport.restore(app,records,review);}catch(Exception error){failure="Restore needs attention: "+notice(error)+" Review current records before retrying.";}finally{try{review.close();}catch(IOException cleanup){if(failure.isEmpty())result+=" Private staging cleanup needs attention.";else failure+=" Private staging cleanup needs attention.";}owned=null;}String done=result,error=failure;main.post(()->publish(new State(error.isEmpty()?Phase.DONE:Phase.ERROR,null,error.isEmpty()?done:error)));});}
 boolean restoring(){return state.phase==Phase.RESTORING;}
 void close(){if(closed)return;closed=true;observer.clear();if(!restoring()){CancellationSignal pending=signal.get();ParcelFileDescriptor file=descriptor.get();CANCEL.execute(()->{if(pending!=null)pending.cancel();if(file!=null)try{file.close();}catch(IOException ignored){}});}worker.execute(()->{if(owned!=null){try{owned.close();}catch(IOException ignored){}owned=null;}});worker.shutdown();}
}
